-- C10 / P10.2 — social connection/token permission/health evidence with recoverable loss.
create table if not exists public.command_center_social_connection_history (
 owner_id uuid not null references auth.users(id) on delete cascade, connection_event_id text not null check(btrim(connection_event_id)<>''), connection_id text not null check(btrim(connection_id)<>''), canonical_account_id text not null check(btrim(canonical_account_id)<>''), platform_identity_id text not null check(btrim(platform_identity_id)<>''), state text not null check(state in ('connected','disconnected','expired','revoked')), credential_ref text, granted_scopes text[] not null default '{}'::text[], provider_health text not null check(provider_health in ('available','degraded','unavailable')), token_present boolean not null, verified_at timestamptz not null, observed_at timestamptz not null, required_owner_action_ref text, reconnect_ref text, evidence_refs text[] not null check(cardinality(evidence_refs)>0), secrets_exposed boolean not null default false check(secrets_exposed=false), protected_action_authorized boolean not null default false check(protected_action_authorized=false), primary key(owner_id,connection_event_id), unique(owner_id,connection_id,observed_at), check(verified_at<=observed_at), check(credential_ref is null or btrim(credential_ref)<>''), check(state='connected' or (required_owner_action_ref is not null and reconnect_ref is not null))
);
create or replace view public.command_center_social_connections_current with (security_invoker=true) as select distinct on(owner_id,connection_id) owner_id,connection_event_id,connection_id,canonical_account_id,platform_identity_id,state,credential_ref,granted_scopes,provider_health,token_present,verified_at,observed_at,required_owner_action_ref,reconnect_ref,evidence_refs,secrets_exposed,protected_action_authorized from public.command_center_social_connection_history order by owner_id,connection_id,observed_at desc;
create or replace function public.command_center_reject_social_connection_history_mutation() returns trigger language plpgsql set search_path to 'public' as $$ begin raise exception 'Social connection history is immutable'; end $$;
drop trigger if exists command_center_social_connection_history_immutable on public.command_center_social_connection_history; create trigger command_center_social_connection_history_immutable before update or delete on public.command_center_social_connection_history for each row execute function public.command_center_reject_social_connection_history_mutation(); alter table public.command_center_social_connection_history enable row level security; revoke all on table public.command_center_social_connection_history from public,anon,authenticated; grant select,insert on table public.command_center_social_connection_history to authenticated; grant select on table public.command_center_social_connections_current to authenticated;
create policy p10_2_social_connection_owner_select on public.command_center_social_connection_history for select to authenticated using(owner_id=(select auth.uid()) and (select public.is_command_center_authorized()));
create policy p10_2_social_connection_owner_insert on public.command_center_social_connection_history for insert to authenticated with check(owner_id=(select auth.uid()) and (select public.is_command_center_authorized()) and secrets_exposed=false and protected_action_authorized=false);
